n narratives"}, {"id": "ca345096-8444-474b-a68a-b7b8e2d67c63", "type": "concept", "title": "Recruitment"}, {"id": "256bf605-69be-4f3a-9870-9a6a814ca253", "type": "concept", "title": "Retention"}, {"id": "e501da0f-f80f-4ceb-a125-ec2155f15523", "type": "concept", "title": "Exit processes"}], "description": "This subtopic explains how networks, life transitions, meaning crises, and community ties shape conversion."}, {"id": "b4a5bd9c-d948-406c-ba82-20bbbe8b2a23", "type": "subtopic", "title": "Innovation, routinization, and conflict", "children": [{"id": "87b8f675-0d01-4768-8c3b-e16716aaedc2", "type": "concept", "title": "Routinization of charisma"}, {"id": "730b53b7-d530-49eb-96b0-b26b21fb68fc", "type": "concept", "title": "Leadership succession"}, {"id": "363e15b2-7d46-4a67-94b9-9d156ceaa888", "type": "concept", "title": "Schism"}, {"id": "4c541807-249a-41fc-9ad8-81548c76ebb4", "type": "concept", "title": "Legal conflict"}, {"id": "707399ee-6818-4eeb-9e77-93e8619a6096", "type": "concept", "title": "Accommodation"}, {"id": "d4fb64ce-872a-473c-bd3d-acb6d02f601c", "type": "concept", "title": "Assimilation"}], "description": "Students analyze how movements institutionalize charisma, manage dissent, and adapt to legal and cultural pressure."}]}, {"id": "ac933d34-3515-4a01-8d33-e95614e90f20", "type": "topic", "title": "Religion, Globalization, Migration, and Diaspora", "description": "Connects religion to global flows of people, media, money, missions, pilgrimage, conflict, and transnational identity.", "children": [{"id": "542d81fe-0331-4e99-8714-f2c0c79a5f40", "type": "subtopic", "title": "Transnational religion", "children": [{"id": "2145a897-bc26-436f-9c30-57f11c9652d9", "type": "concept", "title": "Transnational fields"}, {"id": "0065be59-e4c7-40fe-9d6c-57cc19746d34", "type": "concept", "title": "Diaspora congregations"}, {"id": "43e20ab5-c2fb-4222-895e-738a832e03aa", "type": "concept", "title": "Remittances"}, {"id": "abce8770-7802-4149-9ec1-80f532ac19ca", "type": "concept", "title": "Mission networks"}, {"id": "0d186732-2b5e-46f4-94e0-ce75974b348a", "type": "concept", "title": "Pilgrimage"}, {"id": "ea655b8a-b437-4d4f-9742-9d43eddd837e", "type": "concept", "title": "Global religious markets"}], "description": "Students see how religious life crosses borders through institutions, kinship, remittances, media, and travel."}, {"id": "2ad4f81b-24d4-4424-ab89-76636bed7817", "type": "subtopic", "title": "Migration and religious adaptation", "children": [{"id": "1c768866-cac8-479c-b830-20418a8da22b", "type": "concept", "title": "Immigrant congregations"}, {"id": "634a14c6-d703-44a7-ab02-121b5f727238", "type": "concept", "title": "Ethnic enclaves"}, {"id": "2852ab3d-ccf9-4291-9188-f7401fb02e17", "type": "concept", "title": "Assimilation"}, {"id": "8ec25dcf-7270-484d-bdde-6a31492de452", "type": "concept", "title": "Second generation"}, {"id": "93156c16-9d27-40b9-8ea2-7391421f3e36", "type": "concept", "title": "Language services"}, {"id": "7a9b87f7-b8a3-4f9e-a97f-b00c84daadb0", "type": "concept", "title": "Legal status"}], "description": "This subtopic examines how migrants use religion for community, identity, services, and negotiation with host societies."}, {"id": "41850112-8a83-42a5-895a-5425557ad710", "type": "subtopic", "title": "Global religion and power", "children": [{"id": "65482469-e212-4367-a8dd-010ed087a147", "type": "concept", "title": "Colonial missions"}, {"id": "8699f600-7677-4ccd-b96f-5199d90a070a", "type": "concept", "title": "Religious NGOs"}, {"id": "fed3c85c-0410-4c58-803b-b5e94dfe81a7", "type": "concept", "title": "Humanitarian aid"}, {"id": "5c488882-8e7f-4acd-ac29-08062780ca50", "type": "concept", "title": "Religious nationalism"}, {"id": "35255419-29c2-4175-af63-600293759833", "type": "concept", "title": "Soft power"}, {"id": "026c2724-f648-47d1-ae3d-20c732b590ab", "type": "concept", "title": "Global publics"}], "description": "Students connect religion to colonialism, development, humanitarianism, nationalism, and geopolitical conflict."}]}, {"id": "8b241275-bc64-4f20-a6ff-99c5e4d308dd", "type": "topic", "title": "Religion, Media, Technology, and Popular Culture", "description": "Explores how religious authority, community, ritual, celebrity, and identity shift across television, music, film, social media, apps, and AI-mediated spaces.", "children": [{"id": "d1a833b9-2b5d-412e-a4fe-8afc6ea09188", "type": "subtopic", "title": "Mediatization of religion", "children": [{"id": "cf23dcae-665f-43e3-bdbd-47fba6f8a276", "type": "concept", "title": "Broadcast religion"}, {"id": "8e7c79b2-dc61-41b5-9858-2ec65a4d931c", "type": "concept", "title": "Televangelism"}, {"id": "ae29e2b5-04a5-42dd-8dcd-c30988bb2778", "type": "concept", "title": "Platform affordances"}, {"id": "df207406-f29c-4a8b-97cf-ccb7b6cc4c9d", "type": "concept", "title": "Algorithmic visibility"}, {"id": "6772b0bb-29ec-4acd-a36e-4cca66777558", "type": "concept", "title": "Influencer authority"}, {"id": "49db5991-afa3-4a44-8ffe-a4a28489ef73", "type": "concept", "title": "Online ritual"}], "description": "Students learn how media formats shape what religious expression looks like and who gains authority."}, {"id": "a3eb41f5-2629-42a3-9cb9-00e6782a2ada", "type": "subtopic", "title": "Popular culture and religious symbols", "children": [{"id": "82be8d4f-e1f6-4871-9fc1-65abec23d545", "type": "concept", "title": "Religious imagery"}, {"id": "acaad818-dc44-46b5-9076-ebe35165ae56", "type": "concept", "title": "Appropriation"}, {"id": "3be93f3d-32bb-4dc9-afca-c6a48e69787f", "type": "concept", "title": "Celebrity religion"}, {"id": "b2df3307-0077-4715-871a-4485d19a5b9c", "type": "concept", "title": "Fandom"}, {"id": "fedab868-aa3b-47f4-8fcd-acdbd0484f4f", "type": "concept", "title": "Mythic narratives"}, {"id": "a3d8f85f-3e39-4f54-9d7d-0490696997e8", "type": "concept", "title": "Moral controversy"}], "description": "This subtopic analyzes how religion circulates through entertainment, fashion, sports, music, memes, and fandom."}, {"id": "198e0c2e-7e94-4c36-b80e-0b5fef8a6cd0", "type": "subtopic", "title": "Digital religion and community", "children": [{"id": "67a3ec43-ec57-4ac6-9dc1-addcc02d9ab9", "type": "concept", "title": "Livestream worship"}, {"id": "a1f4bb88-be2e-4af1-b694-858e3b8ed507", "type": "concept", "title": "Prayer apps"}, {"id": "f393b141-7378-4194-9139-af253001a645", "type": "concept", "title": "Online forums"}, {"id": "e4f093ae-6426-4164-b081-62de6e005612", "type": "concept", "title": "Virtual communities"}, {"id": "2d273f08-2ef2-497d-8838-23c244ca2e58", "type": "concept", "title": "Digital authority"}, {"id": "fb8b374a-3e36-42de-a1fc-a0d1b8bb78b3", "type": "concept", "title": "Data privacy"}], "description": "Students examine online worship, hybrid congregations, digital pilgrimage, religious apps, and networked publics."}]}, {"id": "cf3e3b85-3f19-4e39-83b4-74ea1e850f6c", "type": "topic", "title": "Religion, Violence, Peacebuilding, and Social Conflict", "description": "Treats religion neither as inherently violent nor inherently peaceful, but as embedded in political, historical, economic, and symbolic conflicts.", "children": [{"id": "f5ea2926-03a5-4370-af46-169e02ae653a", "type": "subtopic", "title": "Religion and conflict analysis", "children": [{"id": "2ce7b40b-e219-4dcf-aab8-ee718dea6f59", "type": "concept", "title": "Ethnoreligious conflict"}, {"id": "3b11c21c-0394-47b2-8f37-b1c8e8f87f5a", "type": "concept", "title": "Sacred space"}, {"id": "f57ede3d-9fc5-458b-beaf-76a069a346df", "type": "concept", "title": "Grievance framing"}, {"id": "41db07c0-eb86-4b7a-9895-dc463b770eeb", "type": "concept", "title": "Sectarianism"}, {"id": "e5498c60-9ce0-421d-99a4-2feda86bf3a9", "type": "concept", "title": "Nationalism"}, {"id": "1300f50a-9698-4ffe-ba4d-e385402a3c10", "type": "concept", "title": "Radicalization"}], "description": "Students learn to separate religious narratives from material grievances, state power, ethnicity, and geopolitical interests."}, {"id": "4fd60c4b-b83d-4115-8c39-cc018c7abffe", "type": "subtopic", "title": "Religious peacebuilding", "children": [{"id": "afe2a524-c55d-4659-ab60-7c77c22002c4", "type": "concept", "title": "Interfaith dialogue"}, {"id": "a253764f-baa3-4016-a46b-47cce6b9cecb", "type": "concept", "title": "Mediation"}, {"id": "6c70d14d-2918-47c0-838f-e9b92493e9de", "type": "concept", "title": "Truth commissions"}, {"id": "806feaf1-4280-4438-b4a4-90f4fa6a8597", "type": "concept", "title": "Reconciliation"}, {"id": "b95e83df-5693-48ab-b893-6e4593fa15cb", "type": "concept", "title": "Nonviolence"}, {"id": "671e8c25-b6c2-41ea-9333-c3a712e864f6", "type": "concept", "title": "Restorative justice"}], "description": "This subtopic highlights mediation, reconciliation, interfaith work, restorative practices, and moral repair."}, {"id": "bd032152-fc57-433a-a395-0eca2818151a", "type": "subtopic", "title": "Hate, stigma, and religious minorities", "children": [{"id": "581a32ef-8fe4-41ec-81e8-fcfc8289e1bf", "type": "concept", "title": "Religious prejudice"}, {"id": "0629509e-b44f-4b6f-86ac-9be3e30cb127", "type": "concept", "title": "Hate crimes"}, {"id": "bf9b09dd-757c-4369-b19e-7174bbcb0fd7", "type": "concept", "title": "Surveillance"}, {"id": "b5f823df-e3d3-478f-b5f0-7b8e6ed85df0", "type": "concept", "title": "Securitization"}, {"id": "3954019e-d1e9-4819-9b9e-54b4021cf77e", "type": "concept", "title": "Minority rights"}, {"id": "743360bf-d0c2-476e-93fa-96191f38f2ec", "type": "concept", "title": "Moral panic"}], "description": "Students analyze discrimination, surveillance, hate crimes, Islamophobia, antisemitism, anti-cult panic, and minority protection."}]}, {"id": "02acbf46-3c0c-49ff-8891-e6859234cb49", "type": "topic", "title": "Religion, Economy, Health, and Social Welfare", "description": "Examines how religion interacts with markets, charity, work, health behavior, care institutions, disaster response, and social services.", "children": [{"id": "e3b799b5-fdf5-46de-acbe-cf167c8cb7c0", "type": "subtopic", "title": "Religion and capitalism", "children": [{"id": "7ebb8b4e-adab-4f52-869b-3795ff434b2a", "type": "concept", "title": "Vocation"}, {"id": "080e3ea8-0be7-4a2d-9f5e-21e7168acc48", "type": "concept", "title": "Prosperity gospel"}, {"id": "fb5ee71e-b869-4ecc-84f5-e2af687574c3", "type": "concept", "title": "Stewardship"}, {"id": "1852c749-8d89-401b-9f3e-14b8153c7860", "type": "concept", "title": "Religious markets"}, {"id": "a9c5e1c3-45cf-4899-a515-b10b8da61476", "type": "concept", "title": "Tithing"}, {"id": "72fa277e-6285-43fc-bf75-5860ac8c9131", "type": "concept", "title": "Consumer culture"}], "description": "Students connect religious ethics to work, money, consumption, prosperity teaching, philanthropy, and critique of markets."}, {"id": "34b0a484-ad29-4c9a-b8b8-db7e7de99e67", "type": "subtopic", "title": "Faith-based welfare and humanitarianism", "children": [{"id": "2fb8961c-5aff-4062-8001-424d42191200", "type": "concept", "title": "Charitable choice"}, {"id": "b3fe832e-967a-4386-b4f1-81d349781343", "type": "concept", "title": "Faith-based nonprofits"}, {"id": "7205b85f-48ef-4fd8-b9d2-c5895f7adb5a", "type": "concept", "title": "Mutual aid"}, {"id": "871b24d2-e7a8-4483-8b50-44dc2d015417", "type": "concept", "title": "Disaster relief"}, {"id": "3bca4ceb-a28d-4318-b9a8-df0754715a0d", "type": "concept", "title": "Refugee resettlement"}, {"id": "85b7e692-7071-4117-8300-1a628eab68f4", "type": "concept", "title": "Service provision"}], "description": "This subtopic explores the social service role of congregations, NGOs, charities, hospitals, schools, and mutual aid networks."}, {"id": "f0a92e25-54a6-44c7-a133-9a2389dcf922", "type": "subtopic", "title": "Religion and health", "children": [{"id": "96115a4b-b035-4147-bc67-fb9defc52933", "type": "concept", "title": "Social support"}, {"id": "c4cdc89a-6681-421d-8422-5faaec3d8e24", "type": "concept", "title": "Religious coping"}, {"id": "b98f52fb-18e3-45d1-8dd3-cafb3226dd26", "type": "concept", "title": "Spiritual care"}, {"id": "f807338a-8e98-4aec-87d4-4c73266dc105", "type": "concept", "title": "Health behaviors"}, {"id": "9e909a6f-7ac4-4205-b583-ffd50ee83a82", "type": "concept", "title": "Stigma"}, {"id": "e460cbc0-5500-4d3a-ad8a-7c11c69ea4b0", "type": "concept", "title": "Medical mistrust"}], "description": "Students examine links between religious participation, coping, mental health, social support, stigma, and health institutions."}]}, {"id": "62af9c06-efbb-4642-836f-9bd197968b8d", "type": "topic", "title": "Capstone: Comparative Case Study and Public Sociology", "description": "Integrates theory, method, evidence, and ethics through a research-based case study that communicates sociological insight to a public audience.", "children": [{"id": "d04ecdd2-b868-4518-bc69-0f336361897c", "type": "subtopic", "title": "Designing a comparative case study", "children": [{"id": "fd4bb508-1acf-4ce8-b461-1db926d161c6", "type": "concept", "title": "Case selection"}, {"id": "0ed52bb1-a8ed-4a41-84c2-b9f0fe652f65", "type": "concept", "title": "Comparative logic"}, {"id": "a4eccfa4-cf9d-47dc-a47c-01a80a80a74f", "type": "concept", "title": "Research question"}, {"id": "27c82d58-74a9-4e64-8902-a70933bdd36d", "type": "concept", "title": "Conceptualization"}, {"id": "65f872bf-faf3-4499-9a57-fe9cd458940a", "type": "concept", "title": "Operationalization"}, {"id": "b4b2772f-adde-45a8-a68e-7074184c4b74", "type": "concept", "title": "Evidence matrix"}], "description": "Students learn to build a focused question, choose cases, define concepts, and justify evidence."}, {"id": "18fcc4c8-1e45-4b28-9bff-ce50d7833390", "type": "subtopic", "title": "Analyzing data and building an argument", "children": [{"id": "c4ba057d-77bc-4470-b641-55a8e6f8a745", "type": "concept", "title": "Coding"}, {"id": "d4566a09-5c63-4d96-9744-4ca96821f15a", "type": "concept", "title": "Theme development"}, {"id": "17caeaa4-1be7-4eee-9d3e-1f2bf5444c6f", "type": "concept", "title": "Triangulation"}, {"id": "216e3e5e-d529-41ca-b659-a1091593bfe5", "type": "concept", "title": "Negative cases"}, {"id": "d55859cf-850f-4ac8-bffb-18dd96de2f45", "type": "concept", "title": "Causal caution"}, {"id": "831371d4-6837-475a-a991-c389aa520bb8", "type": "concept", "title": "Argument structure"}], "description": "This subtopic turns notes, data, texts, and interviews into sociological claims supported by evidence."}, {"id": "7a7bd73b-67a0-4e72-98d6-a7551962903b", "type": "subtopic", "title": "Public communication", "children": [{"id": "7cc477b3-da06-49a1-934e-559cf85fc5ac", "type": "concept", "title": "Policy memo"}, {"id": "0a455fb1-05f2-4490-8b1a-9aa9d02288ad", "type": "concept", "title": "Public essay"}, {"id": "080aab07-85fa-45da-8767-a91190879ec2", "type": "concept", "title": "Podcast script"}, {"id": "3899ab0e-bd69-4ef6-a3e1-52b46768a80e", "type": "concept", "title": "Data visualization"}, {"id": "6142e3c7-5d09-4f3e-aa9a-cec99d6e5514", "type": "concept", "title": "Community presentation"}, {"id": "369cc824-8285-4930-ac8c-6f77b33d421e", "type": "concept", "title": "Ethical representation"}], "description": "Students practice translating sociological research into accessible, ethical, and nuanced public-facing work."}]}], "dbBacked": true}$sorejson$::jsonb,
