update public.learning_paths
set
  title = 'Sociology of Religion',
  goal = 'Sociology of Religion',
  summary = 'This course studies religion as a social institution, cultural system, set of practices, source of identity, field of power, and site of social change. Students learn classical and contemporary theories, empirical research methods, and major debates about secularization, pluralism, inequality, politics, globalization, media, conflict, and public life. The syllabus covers core Sociology of Religion topics, then expands them into a more granular upper-division course with research literacy and a capstone case-study component.',
  data = $sorejson${"slug": "sociology-of-religion", "title": "Sociology of Religion", "description": "This course studies religion as a social institution, cultural system, set of practices, source of identity, field of power, and site of social change. Students learn classical and contemporary theories, empirical research methods, and major debates about secularization, pluralism, inequality, politics, globalization, media, conflict, and public life. The syllabus covers core Sociology of Religion topics, then expands them into a more granular upper-division course with research literacy and a capstone case-study component.", "topics": [{"id": "a7a7d9cb-a725-42fc-a0a1-6753ea7ef3e5", "type": "topic", "title": "Sociological Approaches to Religion", "description": "Frames religion as a social phenomenon that can be studied through institutions, meanings, practices, networks, power, and historical change.", "children": [{"id": "c260b0c0-1917-451d-834f-3fa6e315ca22", "type": "subtopic", "title": "Defining religion sociologically", "children": [{"id": "4e2f6a80-15c1-4c10-95b7-e53e61c290b5", "type": "concept", "title": "Substantive definitions"}, {"id": "7a8d7c40-2603-433d-bdaa-39a0f1b77485", "type": "concept", "title": "Functional definitions"}, {"id": "deb614fd-86db-417b-ad87-5e5175cfd375", "type": "concept", "title": "Family resemblance approaches"}, {"id": "d0c23fda-d192-4235-b47d-b8bb2c6ab56b", "type": "concept", "title": "Lived religion"}, {"id": "08ee7baa-3bbc-4f7b-b848-cee5abb6b610", "type": "concept", "title": "Civil religion"}, {"id": "f9714c5c-b066-4d35-85b6-51cc31bb3146", "type": "concept", "title": "Implicit religion"}], "description": "Students learn why definitions matter: they shape what counts as religion, how surveys measure it, and whose practices become visible."}, {"id": "82e9a471-83e1-44ee-8b1a-297dea2216d0", "type": "subtopic", "title": "Levels of analysis", "children": [{"id": "dcf9dd20-8605-4a10-94b7-261ba090a033", "type": "concept", "title": "Micro interaction"}, {"id": "fd5918bf-d54c-4603-923d-889307f3344b", "type": "concept", "title": "Meso organizations"}, {"id": "8feb7eba-2c70-43eb-898d-605e9d95213c", "type": "concept", "title": "Macro institutions"}, {"id": "edade565-397e-46f5-b5c1-205c2c374a36", "type": "concept", "title": "Transnational fields"}, {"id": "c25aa240-7db6-4cae-a912-46a711c3b711", "type": "concept", "title": "Ecological and spatial analysis"}], "description": "This subtopic shows how religion operates simultaneously through personal belief, interaction, organizations, communities, and large institutions."}, {"id": "31dc8fd6-d5a0-4fbf-972c-bcb6bd364903", "type": "subtopic", "title": "Sociological imagination and religion", "children": [{"id": "8324afb1-6576-4c68-b3d3-736da3efe326", "type": "concept", "title": "Biography and history"}, {"id": "0c0f7ab4-aeb6-45a7-bff3-9f8244bf7512", "type": "concept", "title": "Private troubles/public issues"}, {"id": "14920f2e-b684-4e1c-b926-4f3e1d862ef3", "type": "concept", "title": "Social location"}, {"id": "59c6cd68-756b-4975-98e7-91b6b91af077", "type": "concept", "title": "Generational cohort"}, {"id": "1d12ae8a-9b6f-4dbc-b686-0390f04bd6ab", "type": "concept", "title": "Religious switching"}], "description": "The point is to connect biography with history: private faith, doubt, belonging, or exit are linked to social conditions."}]}, {"id": "3ffb0dcf-10d6-4091-a83f-0ced420fc916", "type": "topic", "title": "Classical and Contemporary Theories", "description": "Builds the conceptual toolkit for explaining how religion creates solidarity, legitimates power, organizes meaning, and adapts under modern conditions.", "children": [{"id": "e34ddcec-4c32-4b8c-866e-8211364953e3", "type": "subtopic", "title": "Durkheim and ritual solidarity", "children": [{"id": "39f1b532-2439-4d98-a8ae-c174243548a7", "type": "concept", "title": "Sacred and profane"}, {"id": "85575628-8a0f-459d-bed3-8598fcf21da3", "type": "concept", "title": "Collective effervescence"}, {"id": "3cb175a5-00df-4ba2-a81f-1b8cbb2464a3", "type": "concept", "title": "Totemism"}, {"id": "ed068d47-d276-4497-8fb5-2f9b96266a42", "type": "concept", "title": "Moral community"}, {"id": "a00406e3-bf52-4225-95aa-c28e912fc219", "type": "concept", "title": "Ritual classification"}], "description": "Durkheim helps students see ritual as a social engine that makes collective life feel sacred and real."}, {"id": "5d88d88f-672a-42e8-be5e-f107bf455894", "type": "subtopic", "title": "Marx, ideology, and material life", "children": [{"id": "63226016-667d-4481-9e77-85d248c83377", "type": "concept", "title": "Alienation"}, {"id": "0d1f6e14-ff5b-4625-a15c-b4535feae76f", "type": "concept", "title": "Ideology"}, {"id": "2a5ac882-8f71-4cef-975f-5375e8d8f68f", "type": "concept", "title": "Legitimation"}, {"id": "62039240-22df-4dc4-ad3c-e62a10149cd7", "type": "concept", "title": "Material conditions"}, {"id": "33a62530-f91b-457c-9a10-0bf4b26294ff", "type": "concept", "title": "Liberation theology"}], "description": "Marxist approaches ask how religion can console suffering, express protest, or reinforce class and political arrangements."}, {"id": "60009570-b0c6-4244-ac8e-a4f4e5fc9dc3", "type": "subtopic", "title": "Weber, meaning, and social action", "children": [{"id": "c464b49d-9314-43e2-82a8-dc52fa3c9d22", "type": "concept", "title": "Verstehen"}, {"id": "7db79dcc-3952-46b8-8f21-5b1340f29406", "type": "concept", "title": "Theodicy"}, {"id": "24cc89e6-6a90-4712-8433-3d6343a8a6f0", "type": "concept", "title": "Charisma"}, {"id": "4c5eeb34-739b-413f-bdae-02e891bd2244", "type": "concept", "title": "Asceticism"}, {"id": "58293525-ede6-489a-a090-56e91f1f4d1e", "type": "concept", "title": "Disenchantment"}, {"id": "68eeba85-be40-4936-b3c5-c5dc72665b0e", "type": "concept", "title": "Protestant ethic"}], "description": "Weber connects religious ideas to conduct, authority, rationalization, and the organization of economic and political life."}, {"id": "60a7840e-003d-46dc-a9e7-6f97cf8eb6d8", "type": "subtopic", "title": "Contemporary perspectives", "children": [{"id": "fc6bba58-4975-4c9e-99f7-be7819a16aa8", "type": "concept", "title": "Rational choice"}, {"id": "8dfda0b4-6745-4c79-945a-a609330b37e7", "type": "concept", "title": "Religious economies"}, {"id": "45e6d491-a5b4-4b43-a1d0-645a7a3cb686", "type": "concept", "title": "Practice theory"}, {"id": "31a482bd-2af2-410d-a72a-80b166223c7c", "type": "concept", "title": "Feminist theory"}, {"id": "212382aa-711b-43b0-a522-f555bdd08dcd", "type": "concept", "title": "Postcolonial theory"}, {"id": "1f9ad2e3-ceb9-4287-a168-0dd56fb7bc44", "type": "concept", "title": "Network theory"}], "description": "Newer theories help explain pluralism, embodied practice, gendered authority, markets, networks, and religion beyond formal institutions."}]}, {"id": "a9181c39-e76d-4094-b925-4dabfbb704c4", "type": "topic", "title": "Studying Religion: Methods, Evidence, and Ethics", "description": "Gives students the research craft needed to study religion carefully, respectfully, and empirically across communities and traditions.", "children": [{"id": "565ddddc-fa0a-42bb-b9e6-ba799845d761", "type": "subtopic", "title": "Survey research and measurement", "children": [{"id": "0352d041-4e97-48f3-a32a-b0a24543bdd6", "type": "concept", "title": "Affiliation categories"}, {"id": "58899ffc-01d9-4d9a-952b-3ce0a22e3707", "type": "concept", "title": "Attendance measures"}, {"id": "c349d755-9c67-4f58-bbbf-e4066c9b938b", "type": "concept", "title": "Belief scales"}, {"id": "977a353e-8c4d-473a-8b45-174431c28d52", "type": "concept", "title": "Religious salience"}, {"id": "329c528e-931f-4246-b7b7-7ca9bba58c32", "type": "concept", "title": "Nonresponse bias"}, {"id": "e37a40ae-40a8-4ccc-ae62-975c87ce21cc", "type": "concept", "title": "Longitudinal trends"}], "description": "Students learn how researchers measure affiliation, attendance, belief, prayer, salience, identity, and religious change."}, {"id": "93bdce86-57bf-4f1d-87ab-b0dc11b3cfcf", "type": "subtopic", "title": "Ethnography and participant observation", "children": [{"id": "38dc782c-d9b5-452a-a118-ec45e69f0a8b", "type": "concept", "title": "Fieldnotes"}, {"id": "544beb19-2768-4050-944e-3966518d00f9", "type": "concept", "title": "Thick description"}, {"id": "f4b822c4-7842-42a6-9e38-076957f74379", "type": "concept", "title": "Access and rapport"}, {"id": "c9da4169-c452-4c84-9916-cc47b3613786", "type": "concept", "title": "Reflexivity"}, {"id": "99a92aaf-b3dd-41c0-a150-09d1dba4b9e1", "type": "concept", "title": "Ritual observation"}, {"id": "a9762813-c9d6-41aa-be63-b15508fd7d13", "type": "concept", "title": "Insider/outsider status"}], "description": "The gist is learning how to observe lived religion in context rather than reducing it to official doctrine."}, {"id": "a56b2895-54e4-4424-9cc9-f5ec60d3af17", "type": "subtopic", "title": "Interviews, documents, and digital traces", "children": [{"id": "f65a0c7f-6d9f-41aa-9bf6-314607e034a8", "type": "concept", "title": "Semi-structured interviews"}, {"id": "285b9ba0-b10d-4eac-a3d7-5937ab34f0c5", "type": "concept", "title": "Oral history"}, {"id": "aa18d3e8-d929-4fd2-a168-783e4c0ec53f", "type": "concept", "title": "Content analysis"}, {"id": "22878d7a-c906-4a5b-a406-2ea0dfe97576", "type": "concept", "title": "Discourse analysis"}, {"id": "ad5603de-7c09-49dd-a180-f04382f46788", "type": "concept", "title": "Digital ethnography"}, {"id": "1d43fb8a-0b01-4228-abd8-fb333addce5f", "type": "concept", "title": "Archival sources"}], "description": "Students practice matching evidence to questions, from life histories to sermons, social media, websites, and organizational records."}, {"id": "04b5fc21-d27c-4943-a129-0e840b0b895d", "type": "subtopic", "title": "Ethics of religious research", "children": [{"id": "1411abbe-23a0-404c-bb14-16ef03340d52", "type": "concept", "title": "Informed consent"}, {"id": "5292156b-6e5c-4330-840a-1fb2117cac68", "type": "concept", "title": "Confidentiality"}, {"id": "e9a47568-a60c-4081-b533-7176e8aede89", "type": "concept", "title": "Vulnerable groups"}, {"id": "0ff28c96-241c-4ad7-81b8-415885f5ee94", "type": "concept", "title": "Community accountability"}, {"id": "233c5782-3ded-4754-a812-89f3c9a42f24", "type": "concept", "title": "Anonymization"}, {"id": "ba7aba1e-aa98-4aa2-bfb7-a0174959455b", "type": "concept", "title": "Researcher positionality"}], "description": "This subtopic emphasizes consent, confidentiality, power, representation, and harm reduction in communities where identity is sensitive."}]}, {"id": "b4f3aedb-3365-48a7-84d9-5b7513fc2c4b", "type": "topic", "title": "Ritual, Practice, and Lived Religion", "description": "Moves beyond belief statements to examine what people do: worship, prayer, pilgrimage, food practices, festivals, mourning, healing, and everyday devotion.", "children": [{"id": "d2bcb0ed-1315-42b5-bc3f-ae76b14e22b7", "type": "subtopic", "title": "Ritual form and ritual action", "children": [{"id": "b787c45d-67e9-4272-b26b-feb238b14e8d", "type": "concept", "title": "Rites of passage"}, {"id": "ad234658-e41c-4757-a6ff-5485e2585f8e", "type": "concept", "title": "Calendrical ritual"}, {"id": "a7d9ddb7-fa38-4060-a02b-7750bcc7bdc5", "type": "concept", "title": "Performance"}, {"id": "cfce2989-88b9-4ebd-83ad-25154faf8cdd", "type": "concept", "title": "Embodiment"}, {"id": "5e37db74-393f-4117-aefe-2e27aa23c628", "type": "concept", "title": "Communitas"}, {"id": "a3a7ca28-dd30-44ab-9b1c-7383e333ac94", "type": "concept", "title": "Ritual failure"}], "description": "Students learn how repetition, symbols, bodies, time, and space create shared meaning and social belonging."}, {"id": "c267174b-5268-4680-ac5a-63bc9e4d4c56", "type": "subtopic", "title": "Everyday religious practice", "children": [{"id": "69617498-22e0-42b2-a91c-cf155e63da5f", "type": "concept", "title": "Prayer"}, {"id": "feeec518-b112-4e2f-afd0-415d407843f4", "type": "concept", "title": "Meditation"}, {"id": "3f94814c-77ab-4cdd-a948-aa93798e54f5", "type": "concept", "title": "Foodways"}, {"id": "3c64e849-2059-4912-aa71-f577f65898c7", "type": "concept", "title": "Dress"}, {"id": "03f7bc34-82a3-4298-ba3d-46ec6cd39477", "type": "concept", "title": "Devotional objects"}, {"id": "b96a94b6-b2b3-48d9-b358-6f305170b515", "type": "concept", "title": "Home altars"}, {"id": "81057911-790e-4212-b768-e6db9262dda9", "type": "concept", "title": "Moral habits"}], "description": "The point is to see religion in homes, workplaces, online spaces, neighborhoods, and ordinary routines."}, {"id": "9a779569-c298-4dee-9a8f-3597937dbab5", "type": "subtopic", "title": "Material and sensory religion", "children": [{"id": "6fc72dac-cb1f-4201-a981-f5c321c5d22a", "type": "concept", "title": "Icons and images"}, {"id": "a7fad526-3b38-4a69-b322-fd60bbe2e7f7", "type": "concept", "title": "Sacred architecture"}, {"id": "a3d942ec-2747-4268-94c4-496f24d8a314", "type": "concept", "title": "Music and chant"}, {"id": "c89bc343-2e2d-4b5e-b142-e5f6b0b9d0a1", "type": "concept", "title": "Pilgrimage objects"}, {"id": "338c089b-b78f-4ad0-863f-b386870f7277", "type": "concept", "title": "Sensory regimes"}, {"id": "0fecb5c7-5882-427b-a573-1c63e0ee314a", "type": "concept", "title": "Material culture"}], "description": "This subtopic shows how objects, architecture, sound, images, smell, and movement organize religious experience."}]}, {"id": "85d6a5f6-c418-40b0-80a4-ffbc04d3186a", "type": "topic", "title": "Religious Organizations, Authority, and Leadership", "description": "Examines how religious communities are structured, governed, financed, led, contested, and sustained over time.", "children": [{"id": "f108346f-53b6-4bb3-bfcc-16cdaf94ec12", "type": "subtopic", "title": "Types of religious organization", "children": [{"id": "e5c09b4e-ee2d-4256-bd18-09383e51b3f9", "type": "concept", "title": "Church"}, {"id": "36f217bc-2282-4779-b167-c70f2f54786b", "type": "concept", "title": "Sect"}, {"id": "a1f2a96c-f200-47ab-8efa-c4c34090905a", "type": "concept", "title": "Denomination"}, {"id": "be4d8b8e-ebe4-4bfd-9a54-1d8e806a59c7", "type": "concept", "title": "Cult/New religious movement"}, {"id": "93cd8393-7777-4971-858f-9a2da86e78a6", "type": "concept", "title": "Congregation"}, {"id": "31625990-1f49-4538-86fa-0f4559857329", "type": "concept", "title": "Megachurch"}, {"id": "a635f82e-7316-42ef-a2b9-48ce8ded4f86", "type": "concept", "title": "House church"}], "description": "Students distinguish organizational forms and learn how structure shapes commitment, authority, growth, and conflict."}, {"id": "2563cd6d-e4b1-4d89-88c4-743eabe71537", "type": "subtopic", "title": "Authority and charisma", "children": [{"id": "ad62a874-95c4-4e68-96fc-9891a5aa511e", "type": "concept", "title": "Charismatic authority"}, {"id": "ee54d8fb-6e6a-4256-bc12-ae5c76ea479d", "type": "concept", "title": "Traditional authority"}, {"id": "47ddb13e-b892-46b0-86d3-b79f9f58247b", "type": "concept", "title": "Legal-rational authority"}, {"id": "ded18a90-aa2c-4da7-a2d7-37ddc2b9ce21", "type": "concept", "title": "Clergy professionalization"}, {"id": "03808198-84ab-44fb-b516-0f7551d88453", "type": "concept", "title": "Lay leadership"}, {"id": "9065ec2c-71cc-454a-92e4-2e2b9c21efb8", "type": "concept", "title": "Succession crises"}], "description": "This subtopic explains how leaders gain legitimacy and how communities negotiate prophecy, tradition, bureaucracy, and expertise."}, {"id": "7cad6f40-2cfd-4ca2-9b58-c0d2ae46cef0", "type": "subtopic", "title": "Congregations as social organizations", "children": [{"id": "7d7d5185-ce00-47bc-bd25-abdcd2d91dfe", "type": "concept", "title": "Membership"}, {"id": "e5f76cac-59c5-4590-8bbe-25d4f449cfd7", "type": "concept", "title": "Small groups"}, {"id": "22fee04b-01fa-40de-b976-32608240267c", "type": "concept", "title": "Clergy labor"}, {"id": "bc0c3e14-47fc-4015-9b44-b4b77ee591a4", "type": "concept", "title": "Volunteer systems"}, {"id": "0a286324-d702-44af-8fda-a54a011598ee", "type": "concept", "title": "Budgets and fundraising"}, {"id": "0de7383d-85c6-4ad4-a62b-63cb219d8a1c", "type": "concept", "title": "Governance boards"}, {"id": "67ce0b21-ea65-43dd-b7ac-1bc3c4474001", "type": "concept", "title": "Congregational decline"}], "description": "Students analyze congregations as sites of worship, social capital, mutual aid, conflict, volunteering, and civic participation."}]}, {"id": "1495c372-6822-47bb-8f08-153e57ef7e1d", "type": "topic", "title": "Religion, Identity, and Socialization", "description": "Shows how religious identities are learned, performed, inherited, chosen, revised, and sometimes rejected across the life course.", "children": [{"id": "bd00eae8-ca2d-4fc7-8fc7-e4c17e0eed7b", "type": "subtopic", "title": "Religious socialization", "children": [{"id": "a4bcf6d9-60e0-495f-bbdc-70d3b7061738", "type": "concept", "title": "Family transmission"}, {"id": "5da5ecbc-f78e-46b7-90f9-5e29b05173fa", "type": "concept", "title": "Youth ministry"}, {"id": "9e75e9e3-9ff1-454c-ac17-6cd12dff9988", "type": "concept", "title": "Religious education"}, {"id": "d39cbe9a-28f4-43e6-ac63-51697f73adf0", "type": "concept", "title": "Peer networks"}, {"id": "d381e43d-e085-48ab-98d9-4df785788e63", "type": "concept", "title": "Conversion"}, {"id": "2cdcd0af-b8b1-480b-b894-5d98113d050a", "type": "concept", "title": "Deconversion"}], "description": "Students trace how families, peers, schools, youth groups, media, and institutions transmit religious repertoires."}, {"id": "9a9603dc-216b-43df-a062-60ea040b0dd0", "type": "subtopic", "title": "Identity formation and boundary work", "children": [{"id": "f2a1545f-ff23-479b-af5b-758906d61452", "type": "concept", "title": "Symbolic boundaries"}, {"id": "be41193a-0333-4164-858b-46c7b0fe321d", "type": "concept", "title": "Ethnic religion"}, {"id": "8bbe617b-05c7-417f-805c-f0f86251f238", "type": "concept", "title": "Moral boundaries"}, {"id": "4f4bfaf4-b06e-40c2-b354-bf29a4860333", "type": "concept", "title": "Purity codes"}, {"id": "9592f92c-f7c6-4235-8547-9df8f16c8ad9", "type": "concept", "title": "Boundary maintenance"}, {"id": "19cb185a-4cba-4126-b9f9-ba9e6b37a4a0", "type": "concept", "title": "Boundary crossing"}], "description": "The gist is understanding how people mark who belongs, who does not, and what practices signal membership."}, {"id": "170420a8-9e4c-4f9a-9ccf-f1b9d955700c", "type": "subtopic", "title": "Life course and generational change", "children": [{"id": "689f2b15-9c67-4b9b-af58-ac865dd56ffd", "type": "concept", "title": "Emerging adulthood"}, {"id": "266b96b4-c800-4576-a1a3-3ad0167ddca5", "type": "concept", "title": "Marriage and family formation"}, {"id": "ad1a4ef8-9e40-4e56-9663-0cea1d7ca45e", "type": "concept", "title": "Religious switching"}, {"id": "f801b882-473b-49a6-87c6-a14d93b46eac", "type": "concept", "title": "Aging"}, {"id": "bc88508c-c0d6-4d93-b6bc-c2a3406f6e75", "type": "concept", "title": "Cohort effects"}, {"id": "d9c873c7-fa22-46bd-a8ff-da8ced36afe5", "type": "concept", "title": "Nones"}], "description": "Students learn how religious participation changes through adolescence, adulthood, marriage, migration, parenting, aging, and cohort replacement."}]}, {"id": "c4c78ad1-b601-4dcb-a842-731388bb4908", "type": "topic", "title": "Religion, Inequality, and Intersectionality", "description": "Analyzes how religion intersects with class, race, ethnicity, gender, sexuality, disability, caste, migration status, and colonial histories.", "children": [{"id": "b2f11454-6a7f-4681-8bf0-744dd1d9af6b", "type": "subtopic", "title": "Religion and social stratification", "children": [{"id": "ae21ab0a-8316-4b8d-992a-0f3359a5682d", "type": "concept", "title": "Class composition"}, {"id": "29ec5242-fa5d-4e81-9de8-53912dafb5b9", "type": "concept", "title": "Education"}, {"id": "c83b4495-f631-4f42-8726-8fa94eb48bb6", "type": "concept", "title": "Occupational networks"}, {"id": "06126967-006c-4390-936e-7fced3bc083b", "type": "concept", "title": "Prosperity theology"}, {"id": "70da948d-eb89-4491-909a-303d4e4e1925", "type": 