ndom."}, {"id": "198e0c2e-7e94-4c36-b80e-0b5fef8a6cd0", "type": "subtopic", "title": "Digital religion and community", "children": [{"id": "67a3ec43-ec57-4ac6-9dc1-addcc02d9ab9", "type": "concept", "title": "Livestream worship"}, {"id": "a1f4bb88-be2e-4af1-b694-858e3b8ed507", "type": "concept", "title": "Prayer apps"}, {"id": "f393b141-7378-4194-9139-af253001a645", "type": "concept", "title": "Online forums"}, {"id": "e4f093ae-6426-4164-b081-62de6e005612", "type": "concept", "title": "Virtual communities"}, {"id": "2d273f08-2ef2-497d-8838-23c244ca2e58", "type": "concept", "title": "Digital authority"}, {"id": "fb8b374a-3e36-42de-a1fc-a0d1b8bb78b3", "type": "concept", "title": "Data privacy"}], "description": "Students examine online worship, hybrid congregations, digital pilgrimage, religious apps, and networked publics."}]}, {"id": "cf3e3b85-3f19-4e39-83b4-74ea1e850f6c", "type": "topic", "title": "Religion, Violence, Peacebuilding, and Social Conflict", "description": "Treats religion neither as inherently violent nor inherently peaceful, but as embedded in political, historical, economic, and symbolic conflicts.", "children": [{"id": "f5ea2926-03a5-4370-af46-169e02ae653a", "type": "subtopic", "title": "Religion and conflict analysis", "children": [{"id": "2ce7b40b-e219-4dcf-aab8-ee718dea6f59", "type": "concept", "title": "Ethnoreligious conflict"}, {"id": "3b11c21c-0394-47b2-8f37-b1c8e8f87f5a", "type": "concept", "title": "Sacred space"}, {"id": "f57ede3d-9fc5-458b-beaf-76a069a346df", "type": "concept", "title": "Grievance framing"}, {"id": "41db07c0-eb86-4b7a-9895-dc463b770eeb", "type": "concept", "title": "Sectarianism"}, {"id": "e5498c60-9ce0-421d-99a4-2feda86bf3a9", "type": "concept", "title": "Nationalism"}, {"id": "1300f50a-9698-4ffe-ba4d-e385402a3c10", "type": "concept", "title": "Radicalization"}], "description": "Students learn to separate religious narratives from material grievances, state power, ethnicity, and geopolitical interests."}, {"id": "4fd60c4